const A=require('../server-data/accounts.cjs'),S=require('../server-data/subjects.cjs');module.exports=async(req,res)=>{try{A.guard(req,res);if(req.method!=='GET')return res.status(405).json({error:'Método no permitido.'});const who=await A.requireUser(req,res),q=new URL(req.url,A.APP).searchParams,subject=q.get('subject')||'termicas';if(!S.valid(subject))return res.status(400).json({error:'Materia inválida.'});if(q.get('history')==='1'){const sessions=await A.api('/rest/v1/maq_exam_sessions?user_id=eq.'+who.user.id+'&subject=eq.'+subject+'&status=eq.finished&select=id,topic,finished_at,summary&order=finished_at.desc&limit=10');return res.status(200).json({sessions,subject})}return res.status(200).json(await A.progress(who.user.id,subject))}catch(e){return A.error(res,e)}};
